<div class="appearance-section">
    <h4>Appearance Settings</h4>
    <p class="text-muted">Customize the look and feel of the application.</p>
    <hr />

    <div class="row">
        <div class="col-md-6">
            <!-- Theme -->
            <div class="mb-4">
                <h6 class="fw-semibold">Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme}")" value="@theme"
                               checked="@(Theme == theme)"
                               @onchange="() => Theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h6 class="fw-semibold">Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"fs-{size}")" value="@size"
                               checked="@(FontSize == size)"
                               @onchange="() => FontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6 class="fw-semibold">Language</h6>
                <select class="form-select" @bind="Language">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>

            @if (ShowSuccess)
            {
                <div class="alert alert-success alert-dismissible mt-3 fade show" role="alert">
                    ✅ Appearance settings saved!
                    <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
                </div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-6">
            <h6 class="fw-semibold">Live Preview</h6>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">
