@namespace sv_1e2661adf2e64bd29b0f90eb519a079c.Components.Pages.Settings

<div class="modal-backdrop-custom @(Visible ? "show" : "")" @onclick="OnCancel.InvokeAsync">
</div>
<div class="modal @(Visible ? "d-block" : "d-none")" tabindex="-1" role="dialog">
    <div class="modal-dialog modal-dialog-centered" role="document">
        <div class="modal-content">
            <div class="modal-header">
                <h5 class="modal-title">Revoke Session</h5>
                <button type="button" class="btn-close" @onclick="OnCancel.InvokeAsync"></button>
            </div>
            <div class="modal-body">
                <p>Are you sure you want to revoke this session?</p>
                <p class="mb-0"><strong>@DeviceName</strong> — @Location</p>
            </div>
            <div class="modal-footer">
                <button type="button" class="btn btn-secondary" @onclick="OnCancel.InvokeAsync">Cancel</button>
                <button type="button" class="btn btn-danger" @onclick="OnConfirm.InvokeAsync">Revoke Session</button>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public string DeviceName { get; set; } = "";
    [Parameter] public string Location { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }
}

