@namespace sv_1e2661adf2e64bd29b0f90eb519a079c.Components.Pages.Settings
@using sv_1e2661adf2e64bd29b0f90eb519a079c.Models

<div class="security-section">
    <h4>Security Settings</h4>
    <p class="text-muted">Manage your password, two-factor authentication, and active sessions.</p>
    <hr />

    <!-- Change Password -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             style="cursor: pointer;" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span class="fw-semibold">Change Password</span>
            <span>@(PasswordPanelOpen ? "▲" : "▼")</span>
        </div>
        @if (PasswordPanelOpen)
        {
            <div class="card-body">
                @if (Settings?.LastPasswordChange is not null)
                {
                    <p class="text-muted small">
                        Last changed: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </p>
                }
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="CurrentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="NewPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="ConfirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="alert alert-danger py-2">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="alert alert-success py-2">✅ Password updated successfully!</div>
                }
                <button class="btn btn-primary" @onclick="ChangePasswordAsync"
                        disabled="@IsChangingPassword">
                    @if (IsChangingPassword)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Update Password
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="fw-semibold mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           @bind="TwoFactorEnabled" />
                </div>
            </div>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="card mb-4">
        <div class="card-header fw-semibold">Active Sessions</div>
        <div class="card-body p-0">
            @if (Sessions.Count == 0)
            {
                <p class="p-3 mb-0 text-muted">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead class="table-light">
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td class="text-end">
                                        @if (session.Id != CurrentSessionId)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </div>
    </div>

    <RevokeSessionDialog Visible="@ShowRevokeDialog"
                         DeviceName="@(SessionToRevoke?.Device ?? "")"
                         Location="@(SessionToRevoke?.Location ?? "")"
                         OnConfirm="ConfirmRevokeAsync"
                         OnCancel="CancelRevoke" />
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string current, string newPw)> OnChangePassword { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordError;
    private bool PasswordSuccess;
    private bool IsChangingPassword;

    private bool TwoFactorEnabled;
    private List<ActiveSession> Sessions = new();
    private string CurrentSessionId = "sess-1"; // first session is "current"

    private bool ShowRevokeDialog;
    private ActiveSession? SessionToRevoke;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            TwoFactorEnabled = Settings.TwoFactorEnabled;
            Sessions = new List<ActiveSession>(Settings.Sessions);
            _initialized = true;
        }
    }

    private async Task ChangePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 8)
        {
            PasswordError = "New password must be at least 8 characters.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "Passwords do not match.";
            return;
        }

        IsChangingPassword = true;
        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        IsChangingPassword = false;
        PasswordSuccess = true;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeDialog = true;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            Sessions.RemoveAll(s => s.Id == SessionToRevoke.Id);
            SessionToRevoke = null;
        }
        ShowRevokeDialog = false;
    }

    private void CancelRevoke()
    {
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

