.appearance-section {
    padding: 0.5rem 0;
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

/* Theme variants */
.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background-color: #f8f9fa;
    border-bottom: 1px solid #dee2e6;
}

.preview-light .preview-button {
    background-color: #0d6efd;
    color: white;
    border: none;
    padding: 0.375rem 0.75rem;
    border-radius: 0.25rem;
    cursor: pointer;
}

.preview-dark {
    background-color: #1e1e2e;
    color: #cdd6f4;
}

.preview-dark .preview-header {
    background-color: #181825;
    border-bottom: 1px solid #45475a;
}

.preview-dark .preview-footer {
    color: #a6adc8;
}

.preview-dark .preview-button {
    background-color: #89b4fa;
    color: #1e1e2e;
    border: none;
    padding: 0.375rem 0.75rem;
    border-radius: 0.25rem;
    cursor: pointer;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

.preview-system .preview-header {
    background-color: #f0f0f0;
    border-bottom: 1px solid #ccc;
}

.preview-system .preview-button {
    background-color: #6c757d;
    color: white;
    border: none;
    padding: 0.375rem 0.75rem;
    border-radius: 0.25rem;
    cursor: pointer;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact .preview-header,
.preview-compact .preview-body,
.preview-compact .preview-footer {
    padding: 0.4rem 0.75rem;
}

.preview-compact .preview-body p {
    margin-bottom: 0.25rem;
}

/* Default spacing */
.preview-area:not(.preview-compact) .preview-header,
.preview-area:not(.preview-compact) .preview-body,
.preview-area:not(.preview-compact) .preview-footer {
    padding: 0.75rem 1rem;
}

.preview-area:not(.preview-compact) .preview-body p {
    margin-bottom: 0.75rem;
}

.preview-footer {
    border-top: 1px solid rgba(0, 0, 0, 0.1);
    font-size: 0.85em;
}

